#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int a[10][10];
    int zero_row = -1, zero_col = -1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            if (a[i][j] == 0) {
                zero_row = i;
                zero_col = j;
            }
        }
    }

    long long magic_sum = 0;
    for (int i = 0; i < n; i++) {
        if (i != zero_row) {
            for (int j = 0; j < n; j++) {
                magic_sum += a[i][j];
            }
            break;
        }
    }

    long long known_sum = 0;
    for (int j = 0; j < n; j++) {
        known_sum += a[zero_row][j];
    }

    printf("%lld\n%d\n%d\n", magic_sum - known_sum,
           zero_row + 1, zero_col + 1);

    return 0;
}
```

